import{_ as r,a0 as o,w as i,s as u,ao as s,I as l,x as t,a1 as n,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"Ubuntu 的 Snap、Red Hat 的 Flatpak 这种通吃所有发行版的打包方式真的有用吗？ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 的 Snap、Red Hat 的 Flatpak 这种通吃所有发行版的打包方式真的有用吗？ | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 的 Snap、Red Hat 的 Flatpak 这种通吃所有发行版的打包方式真的有用吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 的 Snap、Red Hat 的 Flatpak 这种通吃所有发行版的打包方式真的有用吗？ | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160625 Ubuntu’s Snap, Red Hat’s Flatpak And Is ‘One Fits All’ Linux Packages Useful","title":"Ubuntu 的 Snap、Red Hat 的 Flatpak 这种通吃所有发行版的打包方式真的有用吗？","tag":"201609","desc":""},"relativePath":"201609/20160625 Ubuntu’s Snap, Red Hat’s Flatpak And Is ‘One Fits All’ Linux Packages Useful.md","filePath":"[post].md"}'),d={name:"201609/20160625 Ubuntu’s Snap, Red Hat’s Flatpak And Is ‘One Fits All’ Linux Packages Useful.md"};function f(k,a,m,x,g,b){const p=o("Link");return i(),u("div",null,[a[18]||(a[18]=s('<h1 id="ubuntu-的-snap、red-hat-的-flatpak-这种通吃所有发行版的打包方式真的有用吗" tabindex="-1">Ubuntu 的 Snap、Red Hat 的 Flatpak 这种通吃所有发行版的打包方式真的有用吗？ <a class="header-anchor" href="#ubuntu-的-snap、red-hat-的-flatpak-这种通吃所有发行版的打包方式真的有用吗" aria-label="Permalink to “Ubuntu 的 Snap、Red Hat 的 Flatpak 这种通吃所有发行版的打包方式真的有用吗？”">​</a></h1><p><img src="http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/06/Flatpak-and-Snap-Packages.jpg" alt=""></p><p><strong>对新一代的打包格式开始渗透到 Linux 生态系统中的深入观察</strong></p><p>最近我们听到越来越多的有关于 Ubuntu 的 Snap 包和由 Red Hat 员工 Alexander Larsson 创造的 Flatpak （曾经叫做 xdg-app）的消息。</p><p>这两种下一代打包方法在本质上拥有相同的目标和特点：即不依赖于第三方系统功能库的独立包装。</p><p>这种 Linux 新技术方向似乎自然会让人脑海中浮现这样的问题：独立包的优点/缺点是什么？这是否让我们拥有更好的 Linux 系统？其背后的动机是什么？</p><p>为了回答这些问题，让我们先深入了解一下 Snap 和 Flatpak。</p><h3 id="动机" tabindex="-1">动机 <a class="header-anchor" href="#动机" aria-label="Permalink to “动机”">​</a></h3>',8)),l("p",null,[a[2]||(a[2]=t("根据 ",-1)),n(p,{href:"http://flatpak.org/press/2016-06-21-flatpak-released.html"},{default:e(()=>[...a[0]||(a[0]=[t("Flatpak",-1)])]),_:1}),a[3]||(a[3]=t(" 和 ",-1)),n(p,{href:"https://insights.ubuntu.com/2016/06/14/universal-snap-packages-launch-on-multiple-linux-distros"},{default:e(()=>[...a[1]||(a[1]=[t("Snap",-1)])]),_:1}),a[4]||(a[4]=t(" 的声明，背后的主要动机是使同一版本的应用程序能够运行在多个 Linux 发行版。",-1))]),a[19]||(a[19]=s('<blockquote><p>“从一开始它的主要目标是允许相同的应用程序运行在各种 Linux 发行版和操作系统上。” —— Flatpak</p></blockquote><blockquote><p>“……‘snap’ 通用 Linux 包格式，使简单的二进制包能够完美的、安全的运行在任何 Linux 桌面、服务器、云和设备上。” —— Snap</p></blockquote><p>说得更具体一点，站在 Snap 和 Flatpak （以下称之为 S&amp;F）背后的人认为，Linux 平台存在碎片化的问题。</p><p>这个问题导致了开发者们需要做许多不必要的工作来使他的软件能够运行在各种不同的发行版上，这影响了整个平台的前进。</p><p>所以，作为 Linux 发行版（Ubuntu 和 Red Hat）的领导者，他们希望消除这个障碍，推动平台发展。</p><p>但是，是否是更多的个人收益刺激了 S&amp;F 的开发？</p><h4 id="个人收益" tabindex="-1">个人收益？ <a class="header-anchor" href="#个人收益" aria-label="Permalink to “个人收益？”">​</a></h4><p>虽然没有任何官方声明，但是试想一下，如果能够创造这种可能会被大多数发行版（即便不是全部）所采用的打包方式，那么这个项目的领导者将可能成为一个能够决定 Linux 大船航向的重要人物。</p><h3 id="优势" tabindex="-1">优势 <a class="header-anchor" href="#优势" aria-label="Permalink to “优势”">​</a></h3><p>这种独立包的好处多多，并且取决于不同的因素。</p><p>这些因素基本上可以归为两类：</p><h4 id="用户角度" tabindex="-1">用户角度 <a class="header-anchor" href="#用户角度" aria-label="Permalink to “用户角度”">​</a></h4><p><strong>+</strong> 从 Liunx 用户的观点来看：Snap 和 Flatpak 带来了将任何软件包（软件或应用）安装在用户使用的任何发行版上的可能性。</p><p>例如你在使用一个不是很流行的发行版，由于开发工作的缺乏，它的软件仓库只有很稀少的包。现在，通过 S&amp;F 你就可以显著的增加包的数量，这是一个多么美好的事情。</p><p><strong>+</strong> 同样，对于使用流行的发行版的用户，即使该发行版的软件仓库上有很多的包，他也可以在不改变它现有的功能库的同时安装一个新的包。</p><p>比方说, 一个 Debian 的用户想要安装一个 “测试分支” 的包，但是他又不想将他的整个系统变成测试版（来让该包运行在更新的功能库上）。现在，他就可以简单的想安装哪个版本就安装哪个版本，而不需要考虑库的问题。</p><p>对于持后者观点的人，可能基本上都是使用源文件编译他们的包的人，然而，除非你使用类似 Gentoo 这样基于源代码的发行版，否则大多数用户将从头编译视为是一个恶心到吐的事情。</p><p><strong>+</strong> 高级用户，或者称之为 “拥有安全意识的用户” 可能会觉得更容易接受这种类型的包，只要它们来自可靠来源，这种包倾向于提供另一层隔离，因为它们通常是与系统包想隔离的。</p><p>* 不论是 Snap 还是 Flatpak 都在不断努力增强它们的安全性，通常他们都使用 “沙盒化” 来隔离，以防止它们可能携带病毒感染整个系统，就像微软 Windows 系统中的 .exe 程序一样。（关于微软和 S&amp;F 后面还会谈到）</p><h4 id="开发者角度" tabindex="-1">开发者角度 <a class="header-anchor" href="#开发者角度" aria-label="Permalink to “开发者角度”">​</a></h4><p>与普通用户相比，对于开发者来说，开发 S&amp;F 包的优点可能更加清楚。这一点已经在上一节有所提示。</p><p>尽管如此，这些优点有：</p><p><strong>+</strong> S&amp;F 通过统一开发的过程，将多发行版的开发变得简单了起来。对于需要将他的应用运行在多个发行版的开发者来说，这大大的减少了他们的工作量。</p><p><strong>++</strong> 因此，开发者能够更容易的使他的应用运行在更多的发行版上。</p><p><strong>+</strong> S&amp;F 允许开发者私自发布他的包，不需要依靠发行版维护者在每一个/每一次发行版中发布他的包。</p><p><strong>++</strong> 通过上述方法，开发者可以不依赖发行版而直接获取到用户安装和卸载其软件的统计数据。</p><p><strong>++</strong> 同样是通过上述方法，开发者可以更好的直接与用户互动，而不需要通过中间媒介，比如发行版这种中间媒介。</p><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to “缺点”">​</a></h3><p><strong>–</strong> 膨胀。就是这么简单。Flatpak 和 Snap 并不是凭空变出来它的依赖关系。相反，它是通过将依赖关系预构建在其中来代替使用系统中的依赖关系。</p><p>就像谚语说的：“山不来就我，我就去就山”。</p><p><strong>–</strong> 之前提到安全意识强的用户会喜欢 S&amp;F 提供的额外的一层隔离，只要该应用来自一个受信任的来源。但是从另外一个角度看，对这方面了解较少的用户，可能会从一个不靠谱的地方弄来一个包含恶意软件的包从而导致危害。</p><p>上面提到的观点可以说是有很有意义的，虽说今天的流行方法，像 PPA、overlay 等也可能是来自不受信任的来源。</p><p>但是，S&amp;F 包更加增加这个风险，因为恶意软件开发者只需要开发一个版本就可以感染各种发行版。相反，如果没有 S&amp;F，恶意软件的开发者就需要创建不同的版本以适应不同的发行版。</p><h3 id="原来微软一直是正确的吗" tabindex="-1">原来微软一直是正确的吗？ <a class="header-anchor" href="#原来微软一直是正确的吗" aria-label="Permalink to “原来微软一直是正确的吗？”">​</a></h3><p>考虑到上面提到的，很显然，在大多数情况下，使用 S&amp;F 包的优点超过缺点。</p><p>至少对于二进制发行版的用户，或者重点不是轻量级的发行版的用户来说是这样的。</p><p>这促使我问出这个问题，可能微软一直是正确的吗？如果是的，那么当 S&amp;F 变成 Linux 的标准后，你还会一如既往的使用 Linux 或者类 Unix 系统吗？</p><p>很显然，时间会是这个问题的最好答案。</p><p>不过，我认为，即使不完全正确，但是微软有些地方也是值得赞扬的，并且以我的观点来看，所有这些方式在 Linux 上都立马能用也确实是一个亮点。</p><hr>',40)),l("p",null,[a[6]||(a[6]=t("via: ",-1)),n(p,{href:"http://www.iwillfolo.com/ubuntus-snap-red-hats-flatpack-and-is-one-fits-all-linux-packages-useful/"},{default:e(()=>[...a[5]||(a[5]=[t("http://www.iwillfolo.com/ubuntus-snap-red-hats-flatpack-and-is-one-fits-all-linux-packages-useful/",-1)])]),_:1})]),l("p",null,[a[10]||(a[10]=t("作者：",-1)),n(p,{href:"http://www.iwillfolo.com/category/editorials/"},{default:e(()=>[...a[7]||(a[7]=[t("Editorials",-1)])]),_:1}),a[11]||(a[11]=t(" 译者：",-1)),n(p,{href:"https://github.com/Chao-zhi"},{default:e(()=>[...a[8]||(a[8]=[t("Chao-zhi",-1)])]),_:1}),a[12]||(a[12]=t(" 校对：",-1)),n(p,{href:"https://github.com/wxy"},{default:e(()=>[...a[9]||(a[9]=[t("wxy",-1)])]),_:1})]),l("p",null,[a[15]||(a[15]=t("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[13]||(a[13]=[t("LCTT",-1)])]),_:1}),a[16]||(a[16]=t(" 原创翻译，",-1)),n(p,{href:"https://linux.cn/"},{default:e(()=>[...a[14]||(a[14]=[t("Linux中国",-1)])]),_:1}),a[17]||(a[17]=t(" 荣誉推出",-1))])])}const L=r(d,[["render",f]]);export{F as __pageData,L as default};
